        ...section('STATE', impact.models.map(value => `+ ${value}`)),
        ...section('RELATIONSHIPS', impact.relationships.map(value => `+ ${value}`)),
        ...section('WORKFLOWS', impact.workflows.map(value => `+ ${value}`)),
        ...section('EVENTS', impact.events.map(value => `+ ${value}`)),
